  { name: 'Orbit', kind: 'STRATEGY / DIGITAL PRODUCT', text: 'Making personal finance feel a little more human.', class: 'orbit', word: 'orbit', detail: 'A concept finance dashboard with approachable onboarding, clear spending insights and a flexible interface system.' },
  { name: 'Terra', kind: 'BRAND IDENTITY / E-COMMERCE', text: 'A fresh digital home for a greener everyday.', class: 'terra', word: 'terra®', detail: 'A concept plant shop combining an earthy visual identity, accessible product discovery and a streamlined shopping journey.' },
  { name: 'Goodkind', kind: 'WEB DESIGN / DEVELOPMENT', text: 'Good food. Good people. A very good website.', class: 'goodkind', word: 'goodkind.', detail: 'A concept neighborhood restaurant with an expressive mobile-first site, clear menu navigation and a welcoming tone of voice.' },
]
const selected = ref<string | null>(null)
function submit() { sent.value = true }
